        // Commands that deliberately keep a styled-text glyph instead of an
        // icon. The font color / highlight pickers render their own "A"/"ab"
        // glyph with an accent color bar in RibbonGroupPanel.CreateColorPicker,
        // which is the clearest representation of what they do.
        private static readonly HashSet<CommandId> TextGlyphOptOuts = new HashSet<CommandId>
        {
            CommandId.FontColorPicker,
            CommandId.FontBackgroundColor,
        };

        // Parsed geometries, cached so every button showing the same icon
        // shares one immutable StreamGeometry instance.
        private static readonly Dictionary<string, StreamGeometry> GeometryCache =
            new Dictionary<string, StreamGeometry>();
        private static readonly object GeometryCacheLock = new object();

        /// <summary>Number of commands with an icon mapping (diagnostics/tests).</summary>
        public static int MappedCommandCount => IconPaths.Count;

        /// <summary>True when this command has a Fluent icon mapping.</summary>
        public static bool HasIcon(CommandId commandId) => IconPaths.ContainsKey(commandId);

        /// <summary>
        /// True when this command is an explicit text-glyph opt-out (renders a
        /// styled text glyph by design, not because an icon is missing).
        /// </summary>
        public static bool UsesTextGlyph(CommandId commandId) => TextGlyphOptOuts.Contains(commandId);

        /// <summary>
        /// The cached geometry for this command's icon, or null when the
        /// command has no icon mapping. Throws nothing for unmapped commands.
        /// </summary>
        public static StreamGeometry GetIcon(CommandId commandId)
        {
            if (!IconPaths.TryGetValue(commandId, out string pathData))
                return null;

            lock (GeometryCacheLock)
            {
                if (!GeometryCache.TryGetValue(pathData, out StreamGeometry geometry))
                {
                    geometry = StreamGeometry.Parse(pathData);
                    GeometryCache.Add(pathData, geometry);
                }
                return geometry;
            }
        }

        /// <summary>
        /// Raw SVG path markup for this command's icon, or null when unmapped.
        /// Exposed for tests that validate the embedded path data.
        /// </summary>
        public static string GetIconPathData(CommandId commandId) =>
            IconPaths.TryGetValue(commandId, out string pathData) ? pathData : null;
    }
